package dev.hatek.quickembedded;


final class QuickUtilAtlasPart0000 {
    private QuickUtilAtlasPart0000() {}
    static void put(byte[] output, int offset) {
        int cursor = offset;
        cursor = QuickUtilAtlas.copy(output, cursor, "");
        if (cursor != offset + 2898) throw new IllegalStateException("Corrupt embedded data part");
    }
}
